{
  "name": "keep-frontend",
  "version": "0.1.0",
  "private": true,
  "description": "Keep note manager - plain HTML/CSS/JS frontend (no build deps)",
  "scripts": {
    "build": "node copy.js"
  }
}

'use strict';

// Tiny build script: copies the plain HTML/CSS/JS app into dist/.
const fs = require('fs');
const path = require('path');

const src = path.join(__dirname, 'src');
const dist = path.join(__dirname, 'dist');

fs.mkdirSync(dist, { recursive: true });

for (const file of fs.readdirSync(src)) {
  const from = path.join(src, file);
  const to = path.join(dist, file);
  if (fs.statSync(from).isFile()) {
    fs.copyFileSync(from, to);
    console.log(`copied ${path.relative(__dirname, from)} -> ${path.relative(__dirname, to)}`);
  }
}

console.log('build complete: frontend/dist/');

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Roboto', 'Helvetica Neue', Arial, sans-serif;
  background: #fff;
  color: #202124;
}

.app-header {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 64px;
  padding: 0 16px;
  border-bottom: 1px solid #e0e0e0;
  position: sticky;
  top: 0;
  background: #fff;
  z-index: 10;
}

.icon-button {
  border: none;
  background: none;
  border-radius: 50%;
