'use strict';

// Keep - plain JS frontend. Talks to the backend JSON API under /api/.
(function () {
  const state = {
    notes: [],
    labels: [],
    view: 'notes',
    search: '',
    trash: [],
  };

  const $ = (sel) => document.querySelector(sel);
  const $$ = (sel) => Array.from(document.querySelectorAll(sel));

  // ---------- API ----------
  async function api(path, options) {
    const res = await fetch('/api' + path, {
      headers: { 'Content-Type': 'application/json' },
      ...options,
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.error || ('HTTP ' + res.status));
    return data;
  }

  const API = {
    listNotes: () => api('/notes'),
    createNote: (note) => api('/notes', { method: 'POST', body: JSON.stringify(note) }),
    updateNote: (id, patch) => api('/notes/' + id, { method: 'PATCH', body: JSON.stringify(patch) }),
    deleteNote: (id) => api('/notes/' + id, { method: 'DELETE' }),
    listLabels: () => api('/labels'),
  };

  // ---------- Rendering ----------
  function esc(text) {
    const div = document.createElement('div');
    div.textContent = text == null ? '' : String(text);
    return div.innerHTML;
  }

  function noteTags(note) {
    const tags = (note.labels || []).filter(Boolean);
    if (!tags.length) return '';
    return '<div class="note-tags">' + tags.map((t) => '<span class="note-tag">' + esc(t) + '</span>').join('') + '</div>';
  }

  function noteCardHTML(note) {
    return (
      '<div class="note-card' + (note.pinned ? ' pinned' : '') + '" data-id="' + esc(note.id) + '" data-title="' + esc(note.title) + '">' +
        '<div class="note-actions">' +
          '<button class="icon-button note-action-pin" title="' + (note.pinned ? 'Unpin' : 'Pin') + '" aria-label="' + (note.pinned ? 'Unpin' : 'Pin') + '">' +
            '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path fill="currentColor" d="M17 4a2 2 0 0 0-2-2H9a2 2 0 0 0-2 2v1H5v2h2v7l-2 2v2h6v4l1 1 1-1v-4h6v-2l-2-2V7h2V5h-2V4z"/></svg>' +
          '</button>' +
          '<button class="icon-button note-action-more" title="More" aria-label="More">' +
            '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path fill="currentColor" d="M12 8a2 2 0 1 1 0-4 2 2 0 0 1 0 4zm0 6a2 2 0 1 1 0-4 2 2 0 0 1 0 4zm0 6a2 2 0 1 1 0-4 2 2 0 0 1 0 4z"/></svg>' +
          '</button>' +
        '</div>' +
        (note.title ? '<div class="note-title">' + esc(note.title) + (note.pinned ? '<span class="pin-indicator">&#128204;</span>' : '') + '</div>' : '') +
        (note.content ? '<div class="note-content">' + esc(note.content) + '</div>' : '') +
        noteTags(note) +
      '</div>'
    );
  }

  function visibleNotes() {
    let list = state.notes.filter((n) => !n.deleted);
    if (state.view === 'archive') list = list.filter((n) => n.archived);
    else list = list.filter((n) => !n.archived);

    if (state.search) {
      const q = state.search.toLowerCase();
      list = list.filter((n) =>
        (n.title || '').toLowerCase().includes(q) || (n.content || '').toLowerCase().includes(q) ||
        (n.labels || []).some((l) => String(l).toLowerCase().includes(q))
      );
    }
    return list;
  }

  function render() {
    const list = visibleNotes();
    const pinned = list.filter((n) => n.pinned);
    const others = list.filter((n) => !n.pinned);

    $('#pinned-notes').innerHTML = pinned.map(noteCardHTML).join('');
    $('#others-notes').innerHTML = others.map(noteCardHTML).join('');

    const hasAny = pinned.length + others.length > 0;
    $('#pinned-section').style.display = pinned.length ? '' : 'none';
    $('#others-section').style.display = others.length ? '' : 'none';
    $('#empty-state').hidden = hasAny;

    const sections = ['pinned-section', 'others-section'];
    if (state.view === 'archive') sections.forEach((s) => { if (state.notes.some((n) => n.archived && !n.deleted)) $('#archive-header').style.display = ''; });
  }

  // ---------- Composer / note form ----------
  function openComposer() {
    const composer = $('#composer');
    composer.innerHTML =
      '<form id="note-form">' +
        '<input id="note-title" name="title" placeholder="Title" aria-label="Title" autocomplete="off" />' +
        '<textarea id="note-content" name="content" placeholder="Take a note..." aria-label="Take a note"></textarea>' +
        '<div class="form-actions">' +
          '<div class="actions-right">' +
            '<button type="button" class="btn pin-btn" aria-label="Pin">Pin</button>' +
          '</div>' +
          '<button type="submit" class="btn primary">Close</button>' +
        '</div>' +
      '</form>';
    composer.removeAttribute('role');
    composer.removeAttribute('tabindex');
    $('#note-title').focus();
  }

  function closeComposer() {
    const title = $('#note-title') ? $('#note-title').value.trim() : '';
    const content = $('#note-content') ? $('#note-content').value.trim() : '';
    const pinBtn = $('.pin-btn');
    const pinned = pinBtn && pinBtn.classList.contains('active');

    if (title || content) {
      API.createNote({ title, content, pinned }).then((note) => {
        state.notes.unshift(note);
        render();
      }).catch((err) => toast(err.message));
    }
    resetComposer();
  }

  function resetComposer() {
    $('#composer').innerHTML = '<span id="composer-hint" class="composer-hint">Take a note...</span>';
    $('#composer').setAttribute('role', 'button');
    $('#composer').setAttribute('tabindex', '0');
  }

  // ---------- Note actions ----------
  function showMenu(note, anchor) {
    const existing = $('#note-menu');
    if (existing) existing.remove();

    const menu = document.createElement('div');
    menu.id = 'note-menu';
    menu.className = 'note-menu';
    menu.style.position = 'absolute';
    menu.style.zIndex = '60';
    menu.style.background = '#fff';
    menu.style.border = '1px solid #e0e0e0';
    menu.style.borderRadius = '8px';
    menu.style.boxShadow = '0 2px 8px rgba(0,0,0,0.25)';
    menu.style.padding = '4px 0';
    menu.style.minWidth = '180px';

    const items = [
      { label: note.pinned ? 'Unpin' : 'Pin note', action: () => API.updateNote(note.id, { pinned: !note.pinned }).then((n) => { replaceNote(n); render(); }) },
      { label: note.archived ? 'Unarchive' : 'Archive', action: () => API.updateNote(note.id, { archived: !note.archived }).then((n) => { replaceNote(n); render(); }) },
      { label: 'Delete note', action: () => deleteNote(note) },
    ];

    items.forEach((item) => {
      const el = document.createElement('button');
      el.type = 'button';
      el.textContent = item.label;
      el.style.cssText = 'display:block;width:100%;text-align:left;padding:8px 16px;border:none;background:none;cursor:pointer;font-size:14px;font-family:inherit;';
      el.addEventListener('mouseenter', () => { el.style.background = '#f1f3f4'; });
      el.addEventListener('mouseleave', () => { el.style.background = 'none'; });
      el.addEventListener('click', () => { menu.remove(); item.action(); });
      menu.appendChild(el);
    });

    document.body.appendChild(menu);
    const rect = anchor.getBoundingClientRect();
    menu.style.left = Math.min(rect.right - 180, window.innerWidth - 200) + 'px';
    menu.style.top = rect.bottom + 'px';

    const dismiss = (e) => {
      if (!menu.contains(e.target)) menu.remove();
      document.removeEventListener('click', dismiss);
    };
    setTimeout(() => document.addEventListener('click', dismiss), 0);
  }

  function replaceNote(updated) {
    const i = state.notes.findIndex((n) => n.id === updated.id);
    if (i >= 0) state.notes[i] = updated;
    else state.notes.unshift(updated);
  }

  function deleteNote(note) {
    API.deleteNote(note.id).then(() => {
      state.notes = state.notes.filter((n) => n.id !== note.id);
      render();
      toast('Note deleted', { action: { label: 'Undo', fn: () => restoreNote(note) } });
    }).catch((err) => toast(err.message));
  }

  function restoreNote(note) {
    API.createNote(note).then((n) => {
      replaceNote(n);
      render();
    }).catch(() => {});
  }

  // ---------- Toast ----------
  let toastTimer = null;
  function toast(message, opts) {
    const el = $('#toast');
    el.hidden = false;
    el.innerHTML = '<span>' + esc(message) + '</span>' +
      (opts && opts.action ? '<button class="toast-action">' + esc(opts.action.label) + '</button>' : '') +
      '<button class="toast-close" aria-label="Close">&#10005;</button>';
    el.querySelector('.toast-close').addEventListener('click', hideToast);
    if (opts && opts.action) {
      el.querySelector('.toast-action').addEventListener('click', () => { opts.action.fn(); hideToast(); });
    }
    clearTimeout(toastTimer);
    toastTimer = setTimeout(hideToast, 5000);
  }
  function hideToast() {
    $('#toast').hidden = true;
    clearTimeout(toastTimer);
  }

  // ---------- Events ----------
  function bindEvents() {
    $('#menu-button').addEventListener('click', () => $('#sidebar').classList.toggle('collapsed'));

    $('#settings-button').addEventListener('click', () => {
      toast('Settings');
    });

    $('#search-input').addEventListener('input', (e) => {
      state.search = e.target.value.trim();
      render();
    });

    $('#composer').addEventListener('click', (e) => {
      if (!e.target.closest('#note-form')) openComposer();
    });
    $('#composer').addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.target.closest('#note-form')) openComposer();
    });

    $('#composer').addEventListener('submit', (e) => {
      if (e.target.id === 'note-form') { e.preventDefault(); closeComposer(); }
    });

    $('#composer').addEventListener('click', (e) => {
      const pinBtn = e.target.closest('.pin-btn');
      if (pinBtn) {
        pinBtn.classList.toggle('active');
        pinBtn.textContent = pinBtn.classList.contains('active') ? 'Pinned' : 'Pin';
      }
    });

    $('#notes-container').addEventListener('click', (e) => {
      const pinBtn = e.target.closest('.note-action-pin');
      if (pinBtn) {
        e.stopPropagation();
        const card = pinBtn.closest('.note-card');
        const id = card.dataset.id;
        const note = state.notes.find((n) => n.id === id);
        API.updateNote(id, { pinned: !note.pinned }).then((n) => { replaceNote(n); render(); });
        return;
      }
      const moreBtn = e.target.closest('.note-action-more');
      if (moreBtn) {
        e.stopPropagation();
        const card = moreBtn.closest('.note-card');
        const id = card.dataset.id;
        const note = state.notes.find((n) => n.id === id);
        showMenu(note, moreBtn);
        return;
      }
      const card = e.target.closest('.note-card');
      if (card) {
        const id = card.dataset.id;
        const note = state.notes.find((n) => n.id === id);
        if (note) openEditor(note);
      }
    });

    $$('.nav-item').forEach((item) => {
      item.addEventListener('click', () => {
        $$('.nav-item').forEach((x) => x.classList.remove('active'));
        item.classList.add('active');
        state.view = item.dataset.view || 'notes';
        render();
      });
    });
  }

  // ---------- Editor (edit note) ----------
  function openEditor(note) {
    const backdrop = document.createElement('div');
    backdrop.className = 'modal-backdrop';
    backdrop.innerHTML =
      '<div class="modal" role="dialog" aria-label="Edit note">' +
        '<h3>Edit note</h3>' +
        '<input type="text" id="edit-title" aria-label="Title" placeholder="Title" value="' + esc(note.title || '') + '" />' +
        '<textarea id="edit-content" aria-label="Note content" placeholder="Take a note..." style="width:100%;min-height:120px;border:1px solid #e0e0e0;border-radius:4px;padding:8px 12px;font-size:14px;font-family:inherit;margin-top:12px;outline:none;">' + esc(note.content || '') + '</textarea>' +
        '<div class="modal-actions">' +
          '<button class="btn" data-action="close">Close</button>' +
          '<button class="btn primary" data-action="save">Save</button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(backdrop);

    const save = () => {
      const title = backdrop.querySelector('#edit-title').value.trim();
      const content = backdrop.querySelector('#edit-content').value.trim();
      API.updateNote(note.id, { title, content }).then((n) => { replaceNote(n); render(); backdrop.remove(); });
    };

    backdrop.querySelector('[data-action="close"]').addEventListener('click', () => backdrop.remove());
    backdrop.querySelector('[data-action="save"]').addEventListener('click', save);
    backdrop.addEventListener('click', (e) => { if (e.target === backdrop) backdrop.remove(); });
    const titleInput = backdrop.querySelector('#edit-title');
    titleInput.focus();
    titleInput.select();
  }

  // ---------- Init ----------
  async function init() {
    bindEvents();
    try {
      const [notes, labels] = await Promise.all([API.listNotes(), API.listLabels()]);
      state.notes = notes;
      state.labels = labels;
    } catch (err) {
      toast(err.message);
    }
    render();
  }

  init();
})();

{
  "name": "keep-backend",
  "version": "0.1.0",
  "private": true,
  "description": "Keep note manager backend - zero npm dependencies",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "engines": {
    "node": ">=14"
  }
}

'use strict';

// Keep - persistent JSON store.
// Loads backend/data/db.json at startup, rewrites it on every mutation.

const fs = require('fs');
const path = require('path');

const DATA_DIR = path.join(__dirname, 'data');
const DB_FILE = path.join(DATA_DIR, 'db.json');

let data = null;

function defaultData() {
  return { notes: [], labels: [] };
}

function load() {
  try {
    const raw = fs.readFileSync(DB_FILE, 'utf8');
    data = JSON.parse(raw);
  } catch (err) {
    // Missing or corrupt file -> start fresh (and persist the seed).
    data = defaultData();
    persist();
  }
  if (!Array.isArray(data.notes)) data.notes = [];
  if (!Array.isArray(data.labels)) data.labels = [];
  return data;
}

function persist() {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  const tmp = DB_FILE + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify(data, null, 2));
  fs.renameSync(tmp, DB_FILE);
}

function get() {
  return data;
}

function setNotes(notes) {
  data.notes = notes;
  persist();
}

function setLabels(labels) {
  data.labels = labels;
  persist();
}

function saveNote(note) {
  const i = data.notes.findIndex((n) => n.id === note.id);
  if (i >= 0) data.notes[i] = note;
  else data.notes.unshift(note);
  persist();
}

module.exports = { load, persist, get, setNotes, setLabels, saveNote, DB_FILE };

'use strict';

// Keep - backend server.
// Node.js only: http, fs, path, url, crypto. Zero npm dependencies.
// - Serves frontend/dist/ at /
// - JSON APIs under /api/
// - Persistence: backend/data/db.json (loaded at startup, rewritten on mutation)

const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const store = require('./store');

const PORT = Number(process.env.PORT) || 43100;
const DIST_DIR = path.resolve(__dirname, '..', 'frontend', 'dist');

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
};

// ---------- helpers ----------

function sendJSON(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function sendError(res, status, message) {
  sendJSON(res, status, { error: message });
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > 2 * 1024 * 1024) {
        reject(new Error('request body too large'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      if (!raw) return resolve({});
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error('invalid JSON body'));
      }
    });
    req.on('error', reject);
  });
}

function makeId() {
  return crypto.randomUUID();
}

function cleanNote(note) {
  return {
    id: note.id,
    title: typeof note.title === 'string' ? note.title : '',
    content: typeof note.content === 'string' ? note.content : '',
    pinned: !!note.pinned,
    archived: !!note.archived,
    deleted: !!note.deleted,
    color: typeof note.color === 'string' && note.color ? note.color : null,
    labels: Array.isArray(note.labels) ? note.labels.filter((l) => typeof l === 'string') : [],
    createdAt: note.createdAt || new Date().toISOString(),
    updatedAt: note.updatedAt || new Date().toISOString(),
  };
}

// ---------- static file serving ----------

function serveStatic(res, urlPath) {
  let filePath;
  if (urlPath === '/' || urlPath === '') {
    filePath = path.join(DIST_DIR, 'index.html');
  } else {
    filePath = path.join(DIST_DIR, path.normalize(urlPath).replace(/^(\.\.[/\\])+/, ''));
  }

  fs.stat(filePath, (err, stats) => {
    if (!err && stats.isDirectory()) {
      filePath = path.join(filePath, 'index.html');
      fs.stat(filePath, (err2, stats2) => {
        if (err2 || !stats2.isFile()) return sendError(res, 404, 'Not Found');
        sendFile(res, filePath);
      });
      return;
    }
    if (err || !stats.isFile()) return sendError(res, 404, 'Not Found');
    sendFile(res, filePath);
  });
}

function sendFile(res, filePath) {
  const ext = path.extname(filePath).toLowerCase();
  const type = MIME[ext] || 'application/octet-stream';
  fs.readFile(filePath, (err, buf) => {
    if (err) return sendError(res, 500, 'read error');
    res.writeHead(200, { 'Content-Type': type, 'Content-Length': buf.length });
    res.end(buf);
  });
}

// ---------- API router ----------

async function handleAPI(req, res, pathname, query) {
  const method = req.method;
  const parts = pathname.split('/').filter(Boolean); // e.g. ['api', 'notes', '<id>']

  // GET /api/health
  if (method === 'GET' && pathname === '/api/health') {
    return sendJSON(res, 200, { status: 'ok', time: new Date().toISOString() });
  }

  // GET /api/notes
  if (method === 'GET' && pathname === '/api/notes') {
    const all = store.get().notes;
    // query filtering (kept simple; client does most filtering)
    let list = all;
    if (query.deleted !== undefined) {
      const wantDeleted = query.deleted === 'true' || query.deleted === '1';
      list = all.filter((n) => !!n.deleted === wantDeleted);
    } else {
      list = all.filter((n) => !n.deleted);
    }
    return sendJSON(res, 200, list);
  }

  // POST /api/notes
  if (method === 'POST' && pathname === '/api/notes') {
    let body;
    try {
      body = await readBody(req);
    } catch (e) {
      return sendError(res, 400, e.message);
    }
    const now = new Date().toISOString();
    const note = cleanNote({
      id: body.id || makeId(),
      title: body.title,
      content: body.content,
      pinned: body.pinned,
      archived: body.archived,
      deleted: body.deleted,
      color: body.color,
      labels: body.labels,
      createdAt: body.createdAt || now,
      updatedAt: now,
    });
    // When restoring, keep original timestamps.
    if (body.createdAt) note.createdAt = body.createdAt;
    store.saveNote(note);
    return sendJSON(res, 201, note);
  }

  // PATCH /api/notes/:id
  const noteMatch = /^\/api\/notes\/([^/]+)$/.exec(pathname);
  if (noteMatch && method === 'PATCH') {
    const id = decodeURIComponent(noteMatch[1]);
    const existing = store.get().notes.find((n) => n.id === id);
    if (!existing) return sendError(res, 404, 'note not found');
    let body;
    try {
      body = await readBody(req);
    } catch (e) {
      return sendError(res, 400, e.message);
    }
    const merged = Object.assign({}, existing, body, { id: existing.id, updatedAt: new Date().toISOString() });
    const note = cleanNote(merged);
    store.saveNote(note);
    return sendJSON(res, 200, note);
  }

  // DELETE /api/notes/:id
  if (noteMatch && method === 'DELETE') {
    const id = decodeURIComponent(noteMatch[1]);
    const notes = store.get().notes;
    const idx = notes.findIndex((n) => n.id === id);
    if (idx < 0) return sendError(res, 404, 'note not found');
    notes.splice(idx, 1);
    store.setNotes(notes);
    return sendJSON(res, 200, { ok: true });
  }

  // GET /api/labels
  if (method === 'GET' && pathname === '/api/labels') {
    return sendJSON(res, 200, store.get().labels);
  }

  // POST /api/labels
  if (method === 'POST' && pathname === '/api/labels') {
    let body;
    try {
      body = await readBody(req);
    } catch (e) {
      return sendError(res, 400, e.message);
    }
    const name = String(body.name || '').trim();
    if (!name) return sendError(res, 400, 'label name required');
    const labels = store.get().labels;
    if (!labels.some((l) => String(l.name || l).toLowerCase() === name.toLowerCase())) {
      labels.push({ id: makeId(), name });
      store.setLabels(labels);
    }
    return sendJSON(res, 201, labels);
  }

  // DELETE /api/labels/:id
  const labelMatch = /^\/api\/labels\/([^/]+)$/.exec(pathname);
  if (labelMatch && method === 'DELETE') {
    const id = decodeURIComponent(labelMatch[1]);
    const labels = store.get().labels;
    const idx = labels.findIndex((l) => String(l.id || '') === id);
    if (idx < 0) return sendError(res, 404, 'label not found');
    const name = String(labels[idx].name || labels[idx]);
    labels.splice(idx, 1);
    store.setLabels(labels);
    // Remove the label from all notes.
    store.get().notes.forEach((n) => {
      if (Array.isArray(n.labels)) n.labels = n.labels.filter((l) => String(l) !== name);
    });
    store.setNotes(store.get().notes);
    return sendJSON(res, 200, { ok: true });
  }

  return sendError(res, 404, 'api route not found: ' + method + ' ' + pathname);
}

// ---------- server ----------

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const pathname = decodeURIComponent(url.pathname);
  const query = Object.fromEntries(url.searchParams.entries());

  if (pathname.startsWith('/api/')) {
    try {
      await handleAPI(req, res, pathname, query);
    } catch (e) {
      sendError(res, 500, e.message);
    }
    return;
  }

  serveStatic(res, pathname);
});

store.load();
server.listen(PORT, () => {
  console.log(`Keep backend listening on http://127.0.0.1:${PORT}`);
  console.log(`Serving frontend from ${DIST_DIR}`);
});

