// ---------- Composer / note form ----------
function isComposerOpen() {
  return !!document.getElementById('note-form');
}

function setComposerButtonState() {
  const composer = $('#composer');
  if (isComposerOpen()) {
    composer.removeAttribute('role');
    composer.removeAttribute('tabindex');
    composer.removeAttribute('aria-label');
  } else {
    composer.setAttribute('role', 'button');
    composer.setAttribute('tabindex', '0');
    composer.setAttribute('aria-label', 'Take a note');
  }
}

function openComposer() {
  if (isComposerOpen()) return; // editor already open; do not wipe the form
  const composer = $('#composer');
  composer.innerHTML =
    '<form id="note-form">' +
      '<input id="note-title" name="title" placeholder="Title" aria-label="Title" autocomplete="off" />' +
      '<textarea id="note-content" name="content" placeholder="Take a note..." aria-label="Take a note"></textarea>' +
      '<div class="form-actions">' +
        '<div class="actions-right">' +
          '<button type="button" class="btn pin-btn" aria-label="Pin">Pin</button>' +
        '</div>' +
        '<button type="submit" class="btn primary">Close</button>' +
      '</div>' +
    '</form>';
  setComposerButtonState();
  $('#note-title').focus();
}

function closeComposer() {
  if (!isComposerOpen()) return;
  const title = $('#note-title').value.trim();
  const content = $('#note-content').value.trim();
  const pinBtn = $('.pin-btn');
  const pinned = pinBtn && pinBtn.classList.contains('active');

  if (title || content) {
    API.createNote({ title, content, pinned }).then((note) => {
      state.notes.unshift(note);
      render();
    }).catch((err) => toast(err.message));
  }
  resetComposer();
}

function resetComposer() {
  $('#composer').innerHTML = '<span id="composer-hint" class="composer-hint">Take a note...</span>';
  setComposerButtonState();
}

$('#composer').addEventListener('click', (e) => {
  if (e.target.closest('#note-form')) return;
  openComposer();
});
$('#composer').addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && !e.target.closest('#note-form')) openComposer();
  if (e.key === 'Escape' && isComposerOpen() && !e.target.closest('.pin-btn')) closeComposer();
});

